+  const deck = assembleDeck(outline, loaded.result);
+  const fit = estimateSlides(deck.slides);
+  if (fit.length > 0) {
+    findings.push({ heading: "文字が箱からはみ出しそうな箇所 (箱を広げるか、文を縮める)", lines: fit.map(formatFitIssue) });
+  }
