+function describeFitElement(e: FitIssue["element"]): string {
+  if (e === "title") return "題名";
+  if (e === "takeaway") return "一言";
+  return `deck.ts の要素 ${String(e)} (スライドの要素の配列の添字。足した順に 0 から数える)`;
