+
+function formatFitIssue(i: FitIssue): string {
+  return `${i.key} の${describeFitElement(i.element)}: 要る高さ ${i.need.toFixed(2)} インチ、文字を置ける高さ ${i.height.toFixed(2)} インチ、文字の先頭 ${JSON.stringify(i.head)}`;
+}
+
+/**
