432	+++ b/slide-deck/src/pptx/write.ts
433	@@ -0,0 +1,255 @@
434	+// スライドのデータから、pptxgenjs で PowerPoint のファイルを書く (計画の R8・R11・U5)。
435	+// pptxgenjs は、キャッシュの node_modules を起点にした createRequire で読み込む (計画の KTD8)。
436	+// テーマの色は pptxgenjs では書けないので、書いた後に pptx のスキルの scripts/apply_theme.js で書き込む (ファイル src/pptx/build.ts)。
437	+
438	+import { createRequire } from "node:module";
439	+import { join } from "node:path";
440	+import type PptxGenJS from "pptxgenjs";
441	+import { title as titleBox, takeaway as takeawayBox, slide as emptyFigure } from "../data/parts.ts";
442	+import type { SchemeColorName, Theme } from "../data/theme.ts";
443	+import { schemeColorValues } from "../data/theme.ts";
444	+import {
445	+  type Deck,
446	+  type LineElement,
447	+  type Margin,
448	+  type Paragraph,
449	+  type ShapeElement,
450	+  SLIDE_SIZE,
451	+  type Slide,
452	+  type SlideFigure,
453	+  type TextBody,
454	+  type TextBoxElement,
455	+  type ThemeColorName,
456	+} from "../data/types.ts";
457	+
458	+/** pptxgenjs のクラス */
459	+export type PptxGenConstructor = typeof PptxGenJS;
460	+
461	+type Presentation = PptxGenJS;
462	+type PptxSlide = PptxGenJS.Slide;
463	+
464	+/** キャッシュの node_modules から pptxgenjs を読み込む */
465	+export function loadPptxGen(nodeModulesDir: string): PptxGenConstructor {
466	+  // createRequire の起点は、そのディレクトリの中のファイルのパスで渡す (ファイルは無くてよい)
467	+  const require = createRequire(join(nodeModulesDir, "slide-deck-pptx.cjs"));
468	+  const loaded: unknown = require("pptxgenjs");
469	+  if (typeof loaded !== "function") {
470	+    throw new Error(`${nodeModulesDir} の pptxgenjs が、クラスを書き出していない`);
471	+  }
472	+  // pptxgenjs の CommonJS の入口は、クラス PptxGenJS そのものを書き出す
473	+  return loaded as PptxGenConstructor;
474	+}
475	+
476	+/** 題名のプレースホルダーを持つレイアウトの名前 */
477	+export const CONTENT_LAYOUT = "SLIDE_DECK_CONTENT";
478	+
479	+// スライドの大きさのレイアウトの名前。大きさは SLIDE_SIZE から決める
480	+const SLIDE_LAYOUT = "SLIDE_DECK_16x9";
481	+
482	+// 箇条書きの字下げ (ポイント)。Google スライドの字下げ (計画の KTD14) と、はみ出しの見積もり (計画の KTD6) と同じ値
483	+const BULLET_INDENT_PT = 16;
484	+
485	+/**
486	+ * テーマの色の名前を、pptxgenjs の色の名前にする。
487	+ * pptxgenjs は、tx1・tx2・bg1・bg2・accent1〜6 だけをテーマの色 (a:schemeClr) として書き、ほかの文字列は RGB の値として書く。
488	+ * PowerPoint のファイルのマスターは tx1 を dk1 に、bg1 を lt1 に対応させる (要素 p:clrMap) ので、同じ色になる
489	+ */
490	+export function schemeColor(name: ThemeColorName): string {
491	+  switch (name) {
492	+    case "dk1":
493	+      return "tx1";
494	+    case "lt1":
495	+      return "bg1";
496	+    case "dk2":
497	+      return "tx2";
498	+    case "lt2":
499	+      return "bg2";
500	+    default:
501	+      return name;
502	+  }
503	+}
504	+
505	+/** 内側の余白を、pptxgenjs のオプション margin の順序 [左, 右, 下, 上] (ポイント) にする */
506	+function toPptxMargin(m: Margin): [number, number, number, number] {
507	+  return [m.left, m.right, m.bottom, m.top];
508	+}
509	+
510	+/**
511	+ * 段落を、pptxgenjs の文字の部分の配列にする。段落の分け方は部品の関数が決めたものをそのまま使い、pptxgenjs に任せない
512	+ * (型 RunInput の説明)。各段落の最後の部分に breakLine を付け、最後の段落だけは付けない。
513	+ * 部品の関数は横の揃え方を必ず決めるので、pptxgenjs は breakLine でだけ段落を区切る
514	+ */
515	+export function toTextProps(paragraphs: readonly Paragraph[]): PptxGenJS.TextProps[] {
516	+  const props: PptxGenJS.TextProps[] = [];
517	+  paragraphs.forEach((p, pi) => {
518	+    p.runs.forEach((r, ri) => {
519	+      const options: PptxGenJS.TextPropsOptions = {
520	+        fontSize: r.fontSize,
521	+        bold: r.bold,
522	+        color: schemeColor(r.color),
523	+        bullet: p.bullet ? { indent: BULLET_INDENT_PT } : false,
524	+        breakLine: ri === p.runs.length - 1 && pi < paragraphs.length - 1,
525	+      };
526	+      if (r.link !== null) options.hyperlink = { url: r.link };
527	+      props.push({ text: r.text, options });
528	+    });
529	+  });
530	+  return props;
531	+}
532	+
533	+/** 文字の箱の書式 (段落の分け方以外) を、pptxgenjs のオプションにする */
534	+function textBodyOptions(body: TextBody): PptxGenJS.TextPropsOptions {
535	+  return {
536	+    align: body.align,
537	+    valign: body.valign,
538	+    margin: toPptxMargin(body.margin),
539	+    paraSpaceAfter: body.paraSpaceAfter,
540	+  };
541	+}
542	+
543	+function lineOptions(color: ThemeColorName, width: number, dashed: boolean): PptxGenJS.ShapeLineProps {
544	+  return { color: schemeColor(color), width, dashType: dashed ? "dash" : "solid" };
545	+}
546	+
547	+function addShape(pres: Presentation, s: PptxSlide, e: ShapeElement): void {
548	+  const options: PptxGenJS.TextPropsOptions = {
549	+    shape: pres.ShapeType[e.shape],
550	+    x: e.x,
551	+    y: e.y,
552	+    w: e.w,
553	+    h: e.h,
554	+    fill: { color: schemeColor(e.fill.color), transparency: e.fill.transparency },
555	+  };
556	+  if (e.shape === "roundRect") options.rectRadius = e.radius;
557	+  if (e.outline !== null) options.line = lineOptions(e.outline.color, e.outline.width, e.outline.dashed);
558	+  if (e.name !== null) options.objectName = e.name;
559	+  if (e.text === null) {
560	+    s.addShape(pres.ShapeType[e.shape], options);
561	+    return;
562	+  }
563	+  s.addText(toTextProps(e.text.paragraphs), { ...options, ...textBodyOptions(e.text) });
564	+}
565	+
566	+function addTextBox(s: PptxSlide, e: TextBoxElement): void {
567	+  const options: PptxGenJS.TextPropsOptions = {
568	+    x: e.x,
569	+    y: e.y,
570	+    w: e.w,
571	+    h: e.h,
572	+    isTextBox: true,
573	+    ...textBodyOptions(e.text),
574	+  };
575	+  if (e.name !== null) options.objectName = e.name;
576	+  s.addText(toTextProps(e.text.paragraphs), options);
577	+}
578	+
579	+function addLine(pres: Presentation, s: PptxSlide, e: LineElement): void {
580	+  // 矢じりは、始点 (beginArrowType) と終点 (endArrowType) に付ける。
581	+  // 型 LineElement の endArrow は終点、startArrow は始点の矢じり (型の説明)
582	+  const line: PptxGenJS.ShapeLineProps = lineOptions(e.color, e.width, e.dashed);
583	+  if (e.endArrow) line.endArrowType = "triangle";
584	+  if (e.startArrow) line.beginArrowType = "triangle";
585	+  s.addShape(pres.ShapeType.line, { x: e.x, y: e.y, w: e.w, h: e.h, flipH: e.flipH, flipV: e.flipV, line });
586	+}
587	+
588	+/** 部品の関数 title か takeaway が作る文字の箱を取り出す */
589	+function fixedBox(add: (s: SlideFigure, t: string) => void, key: string, t: string): TextBoxElement {
590	+  const fig = emptyFigure(key);
591	+  add(fig, t);
592	+  const [box] = fig.elements;
593	+  if (box?.kind !== "textBox") throw new Error(`題名か一言の部品の関数が、文字の箱を作らなかった (キー ${key})`);
594	+  return box;
595	+}
596	+
597	+/**
598	+ * 題名のプレースホルダーを持つレイアウトを作る。位置と書式は、部品の関数 title が作る箱と同じにする
599	+ * (計画の KTD1。はみ出しの見積もりと Google スライドの指示の作成も、同じ箱を使う)
600	+ */
601	+function defineContentLayout(pres: Presentation): void {
602	+  const box = fixedBox(titleBox, "layout", "");
603	+  const [run] = box.text.paragraphs[0]?.runs ?? [];
604	+  if (run === undefined) throw new Error("題名の部品の関数が、文字の部分を作らなかった");
605	+  pres.defineSlideMaster({
606	+    title: CONTENT_LAYOUT,
607	+    // 背景をテーマの lt1 (背景の色) で塗る。背景を書かないと、PowerPoint のファイルを表示するソフトによって背景の色が違う
608	+    // (macOS の Quick Look では灰色になった)
609	+    background: { color: schemeColor("lt1") },
610	+    objects: [
611	+      {
612	+        placeholder: {
613	+          options: {
614	+            name: "title",
615	+            type: "title",
616	+            x: box.x,
617	+            y: box.y,
618	+            w: box.w,
619	+            h: box.h,
620	+            fontSize: run.fontSize,
621	+            bold: run.bold,
622	+            color: schemeColor(run.color),
623	+            align: box.text.align,
624	+            valign: box.text.valign,
625	+            margin: toPptxMargin(box.text.margin),
626	+          },
627	+          text: "",
628	+        },
629	+      },
630	+    ],
631	+  });
632	+}
633	+
634	+function addSlide(pres: Presentation, slide: Slide): void {
635	+  const s = pres.addSlide({ masterName: CONTENT_LAYOUT });
636	+  const title = fixedBox(titleBox, slide.key, slide.title);
637	+  s.addText(toTextProps(title.text.paragraphs), { placeholder: "title" });
638	+  for (const e of slide.elements) {
639	+    switch (e.kind) {
640	+      case "shape":
641	+        addShape(pres, s, e);
642	+        break;
643	+      case "textBox":
644	+        addTextBox(s, e);
645	+        break;
646	+      case "line":
647	+        addLine(pres, s, e);
648	+        break;
649	+    }
650	+  }
651	+  addTextBox(s, fixedBox(takeawayBox, slide.key, slide.takeaway));
652	+  if (slide.notes !== "") s.addNotes(slide.notes);
653	+}
654	+
655	+/**
656	+ * スライドのデータから PowerPoint のファイルを作り、内容を返す。
657	+ * スライドの大きさは SLIDE_SIZE。テーマのフォントは書くが、テーマの色は書かない (pptxgenjs が書けないため。テーマの色は、ファイル src/pptx/build.ts が pptx のスキルで書き込む)
658	+ */
659	+export async function renderPptx(deck: Deck, PptxGen: PptxGenConstructor): Promise<Buffer> {
660	+  const pres = new PptxGen();
661	+  pres.defineLayout({ name: SLIDE_LAYOUT, width: SLIDE_SIZE.w, height: SLIDE_SIZE.h });
662	+  pres.layout = SLIDE_LAYOUT;
663	+  pres.title = deck.title;
664	+  pres.theme = { headFontFace: deck.theme.fonts.heading, bodyFontFace: deck.theme.fonts.body };
665	+  defineContentLayout(pres);
666	+  for (const slide of deck.slides) addSlide(pres, slide);
667	+  const out = await pres.write({ outputType: "nodebuffer" });
668	+  if (!Buffer.isBuffer(out)) throw new Error("pptxgenjs が、ファイルの内容を Buffer で返さなかった");
669	+  return out;
670	+}
671	+
672	+/** pptx のスキルの scripts/apply_theme.js に渡すテーマ。名前と、テーマの 12 色 (16 進数 6 桁) */
673	+export interface ApplyThemeInput {
674	+  name: string;
675	+  headFontFace: string;
676	+  bodyFontFace: string;
677	+  colors: Record<SchemeColorName, string>;
678	+}
679	+
680	+/** テーマを、pptx のスキルの scripts/apply_theme.js に渡す形にする */
681	+export function applyThemeInput(theme: Theme): ApplyThemeInput {
682	+  return {
683	+    name: theme.name,
684	+    headFontFace: theme.fonts.heading,
685	+    bodyFontFace: theme.fonts.body,
686	+    colors: schemeColorValues(theme),
687	+  };
688	+}
